function detectLanguage() {
  // Manual choice in Settings > config.defaultLanguage > "en".
  var stored = localStorage.getItem("launcher_lang");
  if (stored && i18nTranslations[stored]) return stored;
  var def = config && config.defaultLanguage;
  return def && i18nTranslations[def] ? def : "en";
}

function t(key) {
  var lang = i18nTranslations[currentLang];
  if (lang && lang[key]) return lang[key];
  return i18nTranslations.en[key] || key;
}

function applyLanguage() {
  var isRtl = rtlLanguages.indexOf(currentLang) !== -1;
  document.documentElement.lang = currentLang.replace("_", "-");
  document.documentElement.dir = isRtl ? "rtl" : "ltr";
  document.querySelectorAll("[data-i18n]").forEach(function(el) {
    el.textContent = t(el.getAttribute("data-i18n"));
  });
  document.querySelectorAll("[data-i18n-placeholder]").forEach(function(el) {
    el.placeholder = t(el.getAttribute("data-i18n-placeholder"));
  });
  document.querySelectorAll("[data-i18n-title]").forEach(function(el) {
    el.title = t(el.getAttribute("data-i18n-title"));
  });
  var joinBtn = document.getElementById("join-btn");
  if (joinBtn && !joining) {
    joinBtn.innerHTML = getJoinBtnDefault();
  }
  setStatus(statusNow);
  // Icon-only nav (narrow window or long labels) keeps its names for tooltips and screen readers.
  document.querySelectorAll(".nav-item").forEach(function (n) {
    var s = n.querySelector("span");
    if (s) { n.title = s.textContent; n.setAttribute("aria-label", s.textContent) }
  });
  fitNav();
  // Restore hardcoded name/logo that the data-i18n placeholders above would
  // otherwise overwrite with "Loading...".
  applyBranding();
}

function setLanguage(lang) {
  if (!i18nTranslations[lang]) return;
  currentLang = lang;
  localStorage.setItem("launcher_lang", lang);
  var sel = document.getElementById("lang-select");
  if (sel) sel.value = lang;
  applyLanguage();
  renderContent();
  fetchServerStatus();
  // Parts drawn by code (not data-i18n) need redrawing in the new language.
  if (cleanScan) renderCleanup()
  if (lastGfx) renderGraphics(lastGfx)
  renderPc()
  renderUndo()
  renderUpdate()
  renderAbout()
  syncUsage()
  renderReady()
  refreshJoinButton()
  renderWelcome()
}

function getJoinBtnDefault() {
  if (ready && !ready.redm) return '<i class="ph ph-download-simple"></i><span>' + esc(t("ready.get")) + '</span>';
  if (waitingSlot) return '<span class="join-spinner"></span><span>' + esc(t("join.waiting")) + '</span>';
  if (serverFull()) return '<i class="ph ph-hourglass"></i><span>' + esc(t("join.full")) + '</span>';
  return '<i class="ph-fill ph-play"></i><span>' + esc(t("join.default")) + '</span>';
}

var launcherData = null
// Bump when a release adds something to Tools worth a look: the Tools tab gets a dot until it's opened.
var TOOLS_NEW = "1.3.0"
var config = null
var statusInterval = null
var dataInterval = null

async function init() {
  try {
    document.body.classList.add("intro")
    setTimeout(function () { document.body.classList.remove("intro") }, 1800)
    config = await window.launcher.getConfig()
    currentLang = detectLanguage();
    loadBrandConfig()
    applyBranding()
    refreshArt()
    if (!config.apiUrl) {
      // No panel API: no gallery/staff pages.
      setNavVisible("gallery", false)
      setNavVisible("staff", false)
    }
    // Everything local first: a slow or hanging panel API must not hold up the rest of the launcher.
    initSettings()
    initTools()
    initHelpers()
    applyLanguage()
    document.querySelector('[data-nav="tools"]').classList.toggle("has-new", localStorage.getItem("toolsSeen") !== TOOLS_NEW)
    setStatus("checking")
    fetchLauncherData()
    fetchServerStatus()
    dataInterval = setInterval(fetchLauncherData, 60000)
    statusInterval = setInterval(fetchServerStatus, 30000)
    // Back online: refresh now instead of waiting for the next round.
    window.addEventListener("online", function () { fetchLauncherData(); fetchServerStatus() })
    window.addEventListener("resize", fitNav)
  } catch (err) {
    console.error("Init error:", err)
    document.getElementById("server-name").textContent = t("error.connection")
  }
}

var panelDownSaid = false
async function fetchLauncherData() {
  try {
    if (config.apiUrl) {
      var res = await fetch(config.apiUrl + "/" + config.slug, { signal: AbortSignal.timeout(10000) })
      if (!res.ok) throw new Error("API error")
      launcherData = await res.json()
    } else {
      // Static content straight from config.json.
      launcherData = { launcher: { rules_content: config.rules || "" }, news: config.news || [], changelogs: config.changelogs || [] }
    }
    renderContent()
  } catch (err) {
    console.error("Fetch error:", err)
    // Panel API unreachable and nothing loaded yet: hide what depends on it instead of showing errors.
    if (!launcherData) {
      ["news", "changelog", "rules", "gallery", "staff"].forEach(function (n) { setNavVisible(n, false) })
      document.querySelector(".home-columns").style.display = "none"
      if (!panelDownSaid) { panelDownSaid = true; say(t("panel.down")) }
    }
  }
}

function setNavVisible(nav, show) {
  var b = document.querySelector('.nav-item[data-nav="' + nav + '"]')
  if (b) b.style.display = show ? "" : "none"
}

// Labels that don't fit (Georgian runs much longer than English): show the nav as icons only,
// so the window buttons never get pushed off-screen.
function fitNav() {
  var tabs = document.querySelector(".tabs")
  if (!tabs) return
  document.body.classList.remove("nav-icons")
  if (tabs.scrollWidth > tabs.clientWidth + 1) document.body.classList.add("nav-icons")
}

async function fetchServerStatus() {
  var cfx = getCfxCode()
  document.querySelector(".hero").classList.toggle("no-featured", !cfx)
  var data = null
  if (cfx) {
    try { data = await window.launcher.serverStatus(cfx) } catch (e) {}
  }
  featuredEndpoint = (data && data.endpoint) || null
  featuredLive = data
  syncUsage()
  onFeaturedStatus(data)
  renderStats(data)
  // Fill gaps in the branding from what the server publishes on Cfx.
  if (data && data.online) {
    if (!brand.logo && data.icon) setLogo(data.icon)
    if (!brand.welcomeMessage && data.desc) document.getElementById("welcome-msg").textContent = data.desc
  }
  refreshArt()
  if (data && data.online) {
    setStatus("online")
    updatePing(data.endpoint)
  } else {
    setPing("--")
    setStatus(data && data.reason === "network" ? "noInternet" : "offline")
  }
}

function setPing(text) {
  var sp = document.getElementById("stat-ping"); if (sp) sp.textContent = text
}

// Measures the user's own latency to the server endpoint (ip:port).
async function updatePing(endpoint) {
  if (!endpoint) { setPing("--"); return }
  try {
    var ms = await window.launcher.pingServer(endpoint)
    setPing(ms == null ? "--" : ms + " ms")
  } catch (e) {
    setPing("--")
  }
}

// online | offline | noInternet | checking (before the first answer)
var statusNow = "checking"
function setStatus(s) {
  statusNow = s
  var badge = document.getElementById("status-badge")
  if (!badge) return
  badge.className = "status " + (s === "online" ? "online" : s === "checking" ? "checking" : "offline")
  badge.querySelector("span:last-child").textContent = t("status." + s)
  badge.title = s === "offline" ? t("status.offlineTip") : s === "noInternet" ? t("status.noInternetTip") : ""
}

// All launcher branding lives in config.json under "brand". The values below
// are fallback defaults, used only when config.json omits a field.
var brand = {
  name: "Tiflisi Launcher",
  logo: "",            // blank = the server's Cfx icon
  backgrounds: [],     // images that rotate behind Home; blank = panel gallery, then Cfx banner
  primaryColor: "#d8402f",
  secondaryColor: "#d8402f",
  accentColor: "#fff6ee",
  welcomeMessage: "",  // blank = the server's Cfx description
  cfxCode: ""
}
var featuredEndpoint = null
var featuredLive = null

// Merge config.json's "brand" object over the defaults (ignoring blanks).
function loadBrandConfig() {
  if (config && config.brand) {
    Object.keys(config.brand).forEach(function(k) {
      var v = config.brand[k]
      if (v !== null && v !== undefined && v !== "") brand[k] = v
    })
  }
}

// Resolve the cfx connect code: config override wins, else whatever the API gave.
function getCfxCode() {
  if (brand.cfxCode) return brand.cfxCode
  if (launcherData && launcherData.launcher && launcherData.launcher.cfx_code) return launcherData.launcher.cfx_code
  return ""
}

function applyBranding() {
  var nameEl = document.getElementById("server-name")
  if (nameEl) nameEl.textContent = brand.name
  var tbName = document.getElementById("titlebar-name")
  if (tbName) tbName.textContent = brand.name
  document.title = brand.name
  if (brand.logo) setLogo(brand.logo)
  document.documentElement.style.setProperty("--primary", brand.primaryColor)
  document.documentElement.style.setProperty("--btn-color", brand.secondaryColor)
  document.documentElement.style.setProperty("--btn-text", brand.accentColor)
  var welcomeEl = document.getElementById("welcome-msg")
  if (welcomeEl && brand.welcomeMessage) welcomeEl.textContent = brand.welcomeMessage
}

function setLogo(src) {
  var img = '<img src="' + esc(src) + '" alt="">'
  document.getElementById("logo-wrapper").innerHTML = img
  document.getElementById("titlebar-logo").innerHTML = img
}

// ── Art layer: rotate images behind the app, crossfading between two layers ──
// Source order: brand.backgrounds (config) > panel gallery > the server's Cfx banner (blurred wash).
var art = { key: "", list: [], i: 0, front: null, timer: null }

function refreshArt() {
  var list = [], ambient = false
  if (Array.isArray(brand.backgrounds) && brand.backgrounds.length) list = brand.backgrounds
  else if (currentGalleryData.length) list = currentGalleryData.map(function (g) { return g.url }).slice(0, 8)
  else if (featuredLive && featuredLive.banner) { list = [featuredLive.banner]; ambient = true }
  var key = (ambient ? "a:" : "") + list.join("|")
  if (key === art.key) return
  art.key = key
  art.list = list
  art.i = Math.floor(Math.random() * list.length) // a different opening shot each launch
  document.getElementById("art").classList.toggle("ambient", ambient)
  clearInterval(art.timer)
  if (!list.length) return
  showArt(list[art.i])
  if (list.length > 1) {
    art.timer = setInterval(function () { art.i = (art.i + 1) % art.list.length; showArt(art.list[art.i]) }, 9000)
  }
}

function showArt(url) {
  var pre = new Image()
  pre.onload = function () {
    var next = art.front && art.front.id === "art-a" ? document.getElementById("art-b") : document.getElementById("art-a")
    next.style.backgroundImage = "url(" + JSON.stringify(url) + ")"
    next.classList.remove("show")
    void next.offsetWidth // restart the drift animation
    next.classList.add("show")
    if (art.front) art.front.classList.remove("show")
    art.front = next
  }
  pre.src = url
}

function renderContent() {
  if (!launcherData) return
  renderNews()
  renderChangelog()
  renderRules()
  renderGalleryPage()
  renderStaff()
  // Hide pages that have nothing to show.
  var l = launcherData.launcher || {}
  var hasNews = (launcherData.news || []).length > 0
  var hasLogs = (launcherData.changelogs || []).length > 0
  setNavVisible("news", hasNews)
  setNavVisible("changelog", hasLogs)
  setNavVisible("rules", !!(l.rules_content || l.rules_url))
  setNavVisible("gallery", !!config.apiUrl) // hidden while the panel was down; back once it answers
  setNavVisible("staff", !!config.apiUrl)
  document.querySelector(".home-columns").style.display = hasNews || hasLogs ? "" : "none"
  fitNav()
}

// ── Expandable entry cards (shared by News + Devlog) ──
var openEntries = {}
var newsSeeded = false
var devlogSeeded = false

function toggleEntry(head, key) {
  var card = head.parentNode
  var open = card.classList.toggle("open")
  if (open) openEntries[key] = true
  else delete openEntries[key]
}

function firstLine(s) {
  if (!s) return ""
  var l = String(s).split("\n")[0].trim()
  return l.length > 64 ? l.slice(0, 64) + "…" : l
}

// opts: { key, badge, title, date, body, pinned }
function buildEntryCard(opts) {
  var openClass = openEntries[opts.key] ? " open" : ""
  var head =
    '<button type="button" class="entry-head" data-act="entry" data-arg="' + esc(opts.key) + '">' +
    (opts.pinned ? '<span class="entry-pin">' + esc(t("news.pinned")) + '</span>' : '') +
    (opts.badge ? '<span class="entry-badge">' + esc(opts.badge) + '</span>' : '') +
    '<span class="entry-title">' + esc(opts.title || "") + '</span>' +
    '<span class="entry-date">' + opts.date + '</span>' +
    '<i class="ph ph-caret-down entry-arrow"></i>' +
    '</button>'
  var body = '<div class="entry-body">' + esc(opts.body || "") + '</div>'
  return '<div class="entry-card' + openClass + '">' + head + body + '</div>'
}

// item: a news or devlog entry. Panels send published_at (some only created_at); no date shows nothing.
function dateShort(item) {
  var d = new Date(item.published_at || item.created_at)
  return isNaN(d) ? "" : d.toLocaleDateString(currentLang.replace("_", "-"), { day: "numeric", month: "short" })
}

function renderNews() {
  var news = launcherData.news || []
  var homeContainer = document.getElementById("news-list")
  var fullContainer = document.getElementById("news-list-full")

  if (!news.length) {
    var empty = '<div class="news-empty">' + esc(t("empty.news")) + '</div>'
    if (homeContainer) homeContainer.innerHTML = empty
    if (fullContainer) fullContainer.innerHTML = empty
    return
  }
  // Auto-open the latest news once on the News page.
  if (!newsSeeded) { openEntries["news-f-" + news[0].id] = true; newsSeeded = true }

  // Home: the three latest as tiles; a click opens that story on the News page.
  if (homeContainer) homeContainer.innerHTML = news.slice(0, 3).map(function (n) {
    return '<button class="tile news-tile" data-act="story" data-arg="news|news-f-' + esc(String(n.id)) + '">' +
      '<span class="tile-meta">' + (n.is_pinned ? '<span class="chip accent">' + esc(t("news.pinned")) + '</span>' : '') + esc(dateShort(n)) + '</span>' +
      '<span class="tile-title">' + esc(n.title || "") + '</span>' +
      '<span class="tile-excerpt">' + esc(n.content || "") + '</span></button>'
  }).join("")
  if (fullContainer) fullContainer.innerHTML = news.map(function (item) {
    return buildEntryCard({ key: "news-f-" + item.id, title: item.title, date: dateShort(item), body: item.content, pinned: item.is_pinned })
  }).join("")
}

function openStory(nav, key) {
  openEntries[key] = true
  renderContent()
  switchNav(nav)
}

function renderChangelog() {
  var logs = launcherData.changelogs || []
  var fullContainer = document.getElementById("changelog-list")
  var homeContainer = document.getElementById("devlog-home-list")

  if (!logs.length) {
    var empty = '<div class="news-empty">' + esc(t("empty.changelog")) + '</div>'
    if (fullContainer) fullContainer.innerHTML = empty
    if (homeContainer) homeContainer.innerHTML = empty
    return
  }
  if (!devlogSeeded) { openEntries["dev-f-" + logs[0].id] = true; devlogSeeded = true }

  // Fall back to the first line of the content when no title is set.
  if (homeContainer) homeContainer.innerHTML = logs.slice(0, 4).map(function (l) {
    return '<button class="devlog-row" data-act="story" data-arg="changelog|dev-f-' + esc(String(l.id)) + '">' +
      (l.version ? '<span class="chip">' + esc(l.version) + '</span>' : '') +
      '<span class="devlog-title">' + esc(l.title || firstLine(l.content)) + '</span></button>'
  }).join("")
  if (fullContainer) fullContainer.innerHTML = logs.map(function (item) {
    return buildEntryCard({ key: "dev-f-" + item.id, badge: item.version, title: item.title || firstLine(item.content), date: dateShort(item), body: item.content })
  }).join("")
}

function renderStats(data) {
  // Ping is set separately by updatePing(): the player's own latency.
  document.getElementById("stat-players").textContent =
    data && data.online ? data.clients + " / " + (data.maxClients || "?") : "--"
}

function switchNav(nav) {
  // Rules opens an external link (set in the panel) instead of an in-app page.
  if (nav === "rules") {
    var rurl = launcherData && launcherData.launcher && launcherData.launcher.rules_url
    if (rurl) { window.launcher.openExternal(rurl); return }
  }
  document.querySelectorAll(".nav-item").forEach(function(n) { n.classList.toggle("active", n.dataset.nav === nav) })
  document.querySelectorAll(".content-area").forEach(function(c) { c.classList.toggle("active", c.id === "content-" + nav) })
  document.body.dataset.view = nav // blurs the art behind inner pages
  if (nav === "tools") {
    refreshTools()
    localStorage.setItem("toolsSeen", TOOLS_NEW)
    document.querySelector('[data-nav="tools"]').classList.remove("has-new")
  }
}

var joining = false
function setJoinBusy(label) {
  var btn = document.getElementById("join-btn")
  btn.innerHTML = '<span class="join-spinner"></span><span>' + esc(label) + '</span>'
  btn.style.pointerEvents = "none"
  btn.style.opacity = "0.6"
}
function resetJoinBtn() {
  joining = false
  var btn = document.getElementById("join-btn")
  btn.innerHTML = getJoinBtnDefault()
  btn.style.pointerEvents = ""
  btn.style.opacity = ""
}

// opts.auto: the slot wait joining by itself; its checks ran when the wait started, so no dialogs now
// (the player may have walked away).
async function joinServer(opts) {
  var auto = !!(opts && opts.auto)
  if (joining) return
  // Clicking while waiting for a slot stops waiting.
  if (waitingSlot && !auto) { stopWaiting(); say(t("join.stopped")); return }
  joining = true // from the first click: a second click while a dialog or the switch runs does nothing
  var launched = false
  try {
    await refreshReady() // fresh every time: a branch changed in Tools, a mod, a RedM installed just now
    if (ready && !ready.redm) { window.launcher.openExternal("https://redm.net"); return } // the button says Get RedM
    if (!auto) {
      if (!(await offlineCheckBeforeJoin())) return
      if (!(await modCheckBeforeJoin())) return
      if (!(await branchCheckBeforeJoin())) return
      // Full: wait for a slot, with every question already answered.
      if (serverFull()) { startWaiting(); return }
    }
    if (ready && !ready.game) say(t("ready.gameBad")) // RedM asks for the game folder itself
    setJoinBusy(t("join.connecting"))
    await joinAddress(getCfxCode(), featuredEndpoint, brand.name)
    launched = true
  } catch (e) {
    console.error("join:", e)
  } finally {
    if (launched) setTimeout(resetJoinBtn, 3000)
    else resetJoinBtn()
  }
}

async function offlineCheckBeforeJoin() {
  if (!featuredLive || featuredLive.online) return true // unknown yet, or online
  return !!(await confirmDialog(t("join.offlineTitle").replace("{server}", brand.name), t("join.offlineMsg"), t("join.offlineOk")))
}

// Unrecognised graphics files: offer to move them aside first (the server is told about them at join).
async function modCheckBeforeJoin() {
  if (!ready || !ready.mod || ready.mod.state !== "unknown") return true
  var n = ready.mod.files.length
  var choice = await confirmDialog(t("join.modTitle"), t(n === 1 ? "join.modMsg1" : "join.modMsg").replace("{n}", n).replace("{server}", brand.name),
    t("join.modRemove"), { cancelLabel: t("join.modAnyway") })
  if (choice === null) return false // closed: don't join
  if (choice) { await readyFix("remove-mods"); if (ready && ready.mod && ready.mod.state === "unknown") return false }
  return true
}

async function joinAddress(address, endpoint, name) {
  var result = await window.launcher.joinServer({ address: address || null, endpoint: endpoint, name: name })
  if (result && !result.success) {
    if (result.error === "not_configured") {
      showErrorDialog(t("dialog.serverNotConfigured"), t("dialog.serverNotConfiguredMsg"))
    } else if (result.error === "not_installed") {
      showErrorDialog(t("dialog.notFound").replace("{game}", "RedM"), t("dialog.notFoundMsg").replace("{game}", "RedM"), "https://redm.net")
    }
  }
  return result
}

function showErrorDialog(title, message, downloadUrl) {
  var overlay = document.createElement("div")
  overlay.className = "error-overlay"
  overlay.innerHTML = '<div class="error-dialog" role="alertdialog" aria-modal="true">' +
    '<h3 class="error-title">' + esc(title) + '</h3>' +
    '<p class="error-msg">' + esc(message) + '</p>' +
    '<div class="error-actions">' +
    (downloadUrl ? '<button class="error-btn secondary" data-act="dialog-download" data-arg="' + esc(downloadUrl) + '">' + esc(t("dialog.download")) + '</button>' : '') +
    '<button class="error-btn" data-act="dialog-close">' + esc(t("dialog.ok")) + '</button>' +
    '</div></div>'
  showOverlay(overlay, '[data-act="dialog-close"]')
}

// Every dialog: on top, keyboard focus inside it (Tab cycles, Escape closes), and closable by
// closeOverlays(). onDismiss runs for Escape and closeOverlays (a confirm resolves, for example).
function showOverlay(o, focusSel, onDismiss) {
  var back = document.activeElement
  o.dismiss = function () {
    if (!o.isConnected) return
    o.remove()
    if (back && back.isConnected) back.focus()
    if (onDismiss) onDismiss()
  }
  o.addEventListener("keydown", function (e) {
    if (e.key === "Escape") { e.stopPropagation(); o.dismiss(); return }
    if (e.key !== "Tab") return
    var f = [].filter.call(o.querySelectorAll("button, input, [tabindex]"), function (x) { return !x.disabled && x.offsetParent !== null })
    if (!f.length) return
    if (e.shiftKey && document.activeElement === f[0]) { e.preventDefault(); f[f.length - 1].focus() }
    else if (!e.shiftKey && document.activeElement === f[f.length - 1]) { e.preventDefault(); f[0].focus() }
  })
  document.body.appendChild(o)
  var first = focusSel && o.querySelector(focusSel)
  if (first) first.focus()
}

function closeOverlay(el) {
  var o = el.closest(".error-overlay")
  if (o) o.dismiss ? o.dismiss() : o.remove()
}

function closeOverlays() {
  document.querySelectorAll(".error-overlay").forEach(function (x) { x.dismiss ? x.dismiss() : x.remove() })
}

// ── Updates (GitHub Releases via electron-updater in the main process) ──
// The new version downloads in the background; a small pill in the title bar offers a one-click restart.

var SOURCE_URL = "https://github.com/teddyyGO/tiflisi-redm-launcher"
var appVersion = ""
var updState = { state: "idle" }

function renderUpdate(s) {
  updState = s || updState
  s = updState
  var pill = document.getElementById("update-pill")
  if (s.state === "ready") {
    pill.hidden = false
    pill.disabled = false
    pill.innerHTML = '<i class="ph ph-arrow-circle-up"></i><span>' + esc(t("upd.pill").replace("{v}", s.version)) + '</span>'
    pill.title = s.notes || ""
  } else if (s.state === "downloading") {
    pill.hidden = false
    pill.disabled = true
    pill.innerHTML = '<span class="pill-spinner"></span><span>' + esc(t("upd.downloading").replace("{p}", s.percent || 0)) + '</span>'
    pill.title = ""
  } else {
    pill.hidden = true
  }
  var desc = {
    dev: t("upd.dev"), checking: t("upd.checking"), error: t("upd.error"),
    downloading: t("upd.downloadingLong").replace("{v}", s.version || "").replace("{p}", s.percent || 0),
    ready: t("upd.ready").replace("{v}", s.version || ""),
  }[s.state] || t("upd.latest")
  document.getElementById("upd-desc").textContent = desc
  var btn = document.getElementById("upd-btn")
  btn.textContent = s.state === "ready" ? t("upd.restart") : t("upd.check")
  btn.disabled = s.state === "dev" || s.state === "checking" || s.state === "downloading"
}

function initUpdates() {
  window.launcher.onUpdateState(renderUpdate)
  window.launcher.updateState().then(renderUpdate)
  document.getElementById("upd-btn").onclick = function () {
    if (updState.state === "ready") window.launcher.installUpdate()
    else window.launcher.checkUpdate().then(renderUpdate)
  }
  window.launcher.getVersion().then(function (v) {
    appVersion = v
    renderAbout()
    // First start after an update: say so once.
    var last = localStorage.getItem("lastVersion")
    if (last && last !== v) say(t("upd.done").replace("{v}", v))
    localStorage.setItem("lastVersion", v)
  })
}

// Which commit and GitHub Actions run built this copy (null: built locally, undefined: not read yet).
var buildInfo
function renderAbout() {
  var b = buildInfo
  document.getElementById("about-desc").textContent = t("about.desc").replace("{v}", appVersion) +
    (b === undefined ? "" : " " + (b ? t("about.build").replace("{c}", b.commit.slice(0, 7)) : t("about.local")))
  document.getElementById("build-log").hidden = !b
  document.getElementById("dev-join").hidden = !brand.devCfxCode
}

// Anonymous launcher stats for the featured server (see main.js heartbeat). Owners can switch the
// whole feature off with "usageStats": false; players can turn it off in Settings.
var usageKey = ""
function syncUsage() {
  var allowed = config.usageStats !== false && !!featuredEndpoint
  var on = allowed && localStorage.getItem("usageStats") !== "false"
  document.getElementById("row-stats").hidden = !allowed
  document.getElementById("toggle-usage").checked = on
  document.getElementById("usage-desc").textContent = t("usage.desc").replace("{server}", brand.name)
  var key = [on, featuredEndpoint, currentLang].join("|")
  if (key === usageKey) return
  usageKey = key
  window.launcher.setUsage({ enabled: on, endpoint: featuredEndpoint, lang: currentLang })
}

function initSettings() {
  var openGameBtn = document.getElementById("open-game-btn")
  if (openGameBtn) {
    openGameBtn.addEventListener("click", function () { openGame() })
  }
  if (config.sourceUrl && /^https:\/\//.test(config.sourceUrl)) SOURCE_URL = config.sourceUrl
  initUpdates()
  window.launcher.buildInfo().then(function (b) { buildInfo = b; renderAbout() })
  document.getElementById("toggle-usage").addEventListener("change", function () {
    localStorage.setItem("usageStats", String(this.checked))
    syncUsage()
  })
  // Shows what Windows will really do at sign-in, not what was last clicked here.
  var autoStartToggle = document.getElementById("toggle-autostart")
  if (autoStartToggle) {
    window.launcher.getAutoStart().then(function (on) { autoStartToggle.checked = on })
    autoStartToggle.addEventListener("change", function() {
      window.launcher.setAutoStart(this.checked)
    })
  }
  // Language selector: only languages that are (nearly) fully translated; the rest would be mostly English.
  var full = Object.keys(i18nTranslations.en).length
  var langs = i18nLanguageList.filter(function (l) {
    return l.code === currentLang || Object.keys(i18nTranslations[l.code] || {}).length >= full * 0.9
  })
  var langSelect = document.getElementById("lang-select")
  if (langSelect) {
    langSelect.innerHTML = langs.map(function(l) {
      return '<option value="' + l.code + '"' + (l.code === currentLang ? ' selected' : '') + '>' + l.name + '</option>'
    }).join("")
    langSelect.addEventListener("change", function() {
      setLanguage(this.value)
    })
  }
}

// Safe in text and in quoted attributes (server tags and names land in data-* attributes).
function esc(s) {
  if (!s) return ""
  return String(s).replace(/[&<>"']/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c] })
}

function cleanName(s) {
  if (!s) return ""
  return s.replace(/~[a-zA-Z0-9_]+~/g, "").replace(/[∑¦]/g, "").replace(/\s{2,}/g, " ").trim()
}

var currentGalleryData = []
var lightboxIndex = 0

function renderGalleryPage() {
  var container = document.getElementById("gallery-grid")
  if (!container || !config.apiUrl) return
  container.innerHTML = '<div class="news-empty">' + esc(t("loading.gallery")) + '</div>'
  fetch(config.apiUrl + "/" + config.slug + "/gallery", { signal: AbortSignal.timeout(10000) })
    .then(function(res) { return res.json() })
    .then(function(data) {
      var images = data.gallery || []
      currentGalleryData = images
      refreshArt()
      if (!images.length) {
        container.innerHTML = '<div class="news-empty">' + esc(t("empty.gallery")) + '</div>'
        return
      }
      container.innerHTML = images.map(function(img, i) {
        var authorHtml = img.author_name
          ? '<div class="gallery-author">' +
            (img.author_avatar ? '<img src="' + esc(img.author_avatar) + '" alt="">' : '') +
            '<span>' + esc(img.author_name) + '</span></div>'
          : ''
        return '<div class="gallery-grid-item" role="button" tabindex="0" data-act="lightbox-open" data-arg="' + i + '">' +
          '<img src="' + esc(img.url) + '" alt="' + esc(img.caption || '') + '">' +
          authorHtml + '</div>'
      }).join("")
    })
    .catch(function() {
      container.innerHTML = '<div class="news-empty">' + esc(t("error.galleryFailed")) + '</div>'
    })
}

function openLightbox(index) {
  lightboxIndex = index
  var overlay = document.getElementById("lightbox")
  var img = document.getElementById("lightbox-img")
  var info = document.getElementById("lightbox-info")
  if (!overlay || !img) return
  var item = currentGalleryData[index]
  if (!item) return
  img.src = item.url
  if (info) {
    info.innerHTML = item.author_name
      ? (item.author_avatar ? '<img src="' + esc(item.author_avatar) + '" alt="">' : '') + '<span>' + esc(item.author_name) + '</span>'
      : ''
  }
  overlay.style.display = "flex"
}

function closeLightbox() {
  var overlay = document.getElementById("lightbox")
  if (overlay) overlay.style.display = "none"
}

function lightboxNav(dir) {
  if (!currentGalleryData.length) return
  lightboxIndex = (lightboxIndex + dir + currentGalleryData.length) % currentGalleryData.length
  var img = document.getElementById("lightbox-img")
  var info = document.getElementById("lightbox-info")
  var item = currentGalleryData[lightboxIndex]
  if (!item || !img) return
  img.src = item.url
  if (info) {
    info.innerHTML = item.author_name
      ? (item.author_avatar ? '<img src="' + esc(item.author_avatar) + '" alt="">' : '') + '<span>' + esc(item.author_name) + '</span>'
      : ''
  }
}

function renderRules() {
  var rules = launcherData && launcherData.launcher ? launcherData.launcher.rules_content || "" : ""
  var container = document.getElementById("rules-content")
  if (!container) return
  if (!rules) { container.innerHTML = '<div class="news-empty">' + esc(t("empty.rules")) + '</div>'; return }
  container.innerHTML = simpleMarkdown(rules)
}

function simpleMarkdown(text) {
  return text
    .replace(/^### (.+)$/gm, '<h3>$1</h3>')
    .replace(/^## (.+)$/gm, '<h2>$1</h2>')
    .replace(/^# (.+)$/gm, '<h1>$1</h1>')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.+?)\*/g, '<em>$1</em>')
    .replace(/`(.+?)`/g, '<code>$1</code>')
    .replace(/^> (.+)$/gm, '<blockquote>$1</blockquote>')
    .replace(/^---$/gm, '<hr>')
    .replace(/^- (.+)$/gm, '<li>$1</li>')
    .replace(/(<li>[\s\S]*?<\/li>)/g, '<ul>$1</ul>')
    .replace(/<\/ul>\s*<ul>/g, '')
    .replace(/\n\n/g, '<br><br>')
}

function renderStaff() {
  var container = document.getElementById("staff-grid")
  if (!container || !config.apiUrl) return
  container.innerHTML = '<div class="news-empty">' + esc(t("loading.staff")) + '</div>'
  fetch(config.apiUrl + "/" + config.slug + "/staff", { signal: AbortSignal.timeout(10000) })
    .then(function(res) { return res.json() })
    .then(function(data) {
      var staff = data.staff || []
      if (!staff.length) {
        container.innerHTML = '<div class="news-empty">' + esc(t("empty.staff")) + '</div>'
        return
      }
      container.innerHTML = staff.map(function(m) {
        return '<div class="staff-card">' +
          '<img class="staff-avatar" src="' + esc(m.avatar_url) + '" alt="' + esc(m.username) + '">' +
          '<div class="staff-name">' + esc(m.username) + '</div>' +
          '<div class="staff-role" style="background:' + esc(m.role_color) + '20;color:' + esc(m.role_color) + '">' + esc(m.role_name) + '</div>' +
          '</div>'
      }).join("")
    })
    .catch(function() {
      container.innerHTML = '<div class="news-empty">' + esc(t("error.staffFailed")) + '</div>'
    })
}

// ── Tools tab: client branch, cache, stuck processes, logs ──

var CHANNELS = ["production", "beta", "canary"]

var branchChoice = "production"

function setBranchChoice(ch) {
  branchChoice = ch
  document.querySelectorAll("#branch-seg button").forEach(function (b) {
    b.setAttribute("aria-checked", String(b.dataset.channel === ch))
  })
  document.getElementById("branch-custom-wrap").hidden = ch !== "custom"
}

var toastTimer = null
function say(msg) {
  var el = document.getElementById("tools-status")
  el.textContent = msg
  clearTimeout(toastTimer)
  toastTimer = setTimeout(function () { el.textContent = "" }, 3500)
}

function initTools() {
  var custom = document.getElementById("branch-custom")
  // Server-owner presets from config.branches, e.g. { "label": "128", "channel": "specific/feature/..." }
  var seg = document.getElementById("branch-seg")
  var customBtn = seg.querySelector('[data-channel="custom"]')
  ;(config.branches || []).forEach(function (p) {
    if (!p || !/^[\w./-]+$/.test(p.channel || "") || CHANNELS.indexOf(p.channel) !== -1) return
    var btn = document.createElement("button")
    btn.setAttribute("role", "radio")
    btn.dataset.channel = p.channel
    btn.title = p.channel
    btn.textContent = p.label || p.channel
    seg.insertBefore(btn, customBtn)
    CHANNELS.push(p.channel)
  })
  document.querySelectorAll("#branch-seg button").forEach(function (b) {
    b.onclick = function () { setBranchChoice(b.dataset.channel); if (b.dataset.channel === "custom") custom.focus() }
  })
  var fail = toolFail
  var apply = document.getElementById("branch-apply")
  apply.onclick = busy(apply, async function () {
    var ch = branchChoice === "custom" ? custom.value.trim() : branchChoice
    var r = await window.launcher.setChannel(ch)
    if (!r.success) {
      fail(r)
      if (branchChoice === "custom") { custom.focus(); custom.select() } // keep what was typed, to fix it
      return
    }
    say(r.running ? t("ready.restartHint").replace("{b}", branchLabel(ch)) : t("tools.done") + " " + branchLabel(ch))
    refreshTools()
    refreshReady() // Home and Join see the new branch at once
  })
  var restart = document.getElementById("restart-btn")
  restart.onclick = busy(restart, async function () {
    if ((await window.launcher.redmInfo()).running && !(await confirmDialog(t("tools.killTitle"), t("tools.killMsg"), t("tools.restartBtn"), { danger: true }))) return
    var r = await window.launcher.restartRedm()
    r && r.success ? say(t("tools.restarted")) : fail(r || {})
  })
  var kill = document.getElementById("kill-btn")
  kill.onclick = busy(kill, async function () {
    if (!(await window.launcher.redmInfo()).running) { say(t("tools.notRunning")); return }
    if (!(await confirmDialog(t("tools.killTitle"), t("tools.killMsg"), t("tools.killOk"), { danger: true }))) return
    var r = await window.launcher.killRedm()
    say(r.killed ? t("tools.killed") : t("tools.notRunning"))
    refreshTools()
  })
  var folder = async function (which) { if ((await window.launcher.openFolder(which)) === "missing") say(t("tools.noFolder")) }
  document.getElementById("logs-btn").onclick = function () { folder("logs") }
  document.getElementById("crashes-btn").onclick = function () { folder("crashes") }
  initCleanup(fail)
  initGraphics(fail)
}

// A readable message for a failed tool call. Error codes from Windows (EPERM, EBUSY...) stay as a hint for staff.
function toolFail(r) {
  var e = (r && r.error) || "failed"
  var known = { running: "tools.running", not_installed: "tools.notInstalled", bad_channel: "tools.badChannel", no_settings: "gfx.noSettings" }
  if (e === "cancelled") return
  say(known[e] ? t(known[e]) : t("tools.failed").replace("{code}", e))
}

// Wraps a click handler: the button is disabled until it finishes, so repeated clicks don't run it twice.
function busy(btn, fn) {
  return async function () {
    if (btn.disabled) return
    btn.disabled = true
    try { await fn.apply(this, arguments) } finally { btn.disabled = false }
  }
}

var openingGame = false
async function openGame() {
  if (openingGame) return
  openingGame = true
  try {
    var r = await window.launcher.openGame()
    if (r && !r.success) showErrorDialog(t("dialog.notFound").replace("{game}", "RedM"), t("dialog.notFoundMsg").replace("{game}", "RedM"), "https://redm.net")
    readyAt = 0 // the player may pick the game folder now: re-check when they come back
  } finally {
    setTimeout(function () { openingGame = false }, 3000) // RedM takes a moment to show a window
  }
}

async function refreshTools() {
  refreshCleanup() // draws its rows straight away; sizes fill in as they're measured
  refreshGraphics()
  refreshPc()
  refreshUndo()
  var info = await window.launcher.redmInfo()
  var known = CHANNELS.indexOf(info.channel) !== -1
  setBranchChoice(known ? info.channel : "custom")
  document.getElementById("branch-custom").value = known ? "" : info.channel
}

// Confirmation in the launcher's own (translated) style. Resolves true (OK), false (the cancel button)
// or null (closed: Escape, a click outside). opts: { cancelLabel, danger } (danger: Cancel has the focus).
function confirmDialog(title, message, okLabel, opts) {
  opts = opts || {}
  return new Promise(function (resolve) {
    var o = document.createElement("div")
    o.className = "error-overlay"
    o.innerHTML = '<div class="error-dialog" role="dialog" aria-modal="true"><h3 class="error-title">' + esc(title) + '</h3>' +
      '<p class="error-msg">' + esc(message) + '</p><div class="error-actions">' +
      '<button class="error-btn secondary" data-a="0">' + esc(opts.cancelLabel || t("dialog.cancel")) + '</button>' +
      '<button class="error-btn" data-a="1">' + esc(okLabel) + '</button></div></div>'
    var opened = Date.now()
    o.addEventListener("click", function (e) {
      var b = e.target.closest("[data-a]")
      if (!b && e.target !== o) return
      // The second click of a double-click on the button that opened this lands on the backdrop: ignore it.
      if (!b && Date.now() - opened < 500) return
      o.remove()
      resolve(b ? b.dataset.a === "1" : null)
    })
    showOverlay(o, opts.danger ? '[data-a="0"]' : '[data-a="1"]', function () { resolve(null) })
  })
}

function fmtBytes(b) {
  if (!b) return "0 KB"
  if (b >= 1073741824) return (b / 1073741824).toFixed(1) + " GB"
  if (b >= 1048576) return Math.round(b / 1048576) + " MB"
  return Math.max(1, Math.round(b / 1024)) + " KB"
}

// ── Cleanup ──

var CLEAN_ORDER = ["server", "app", "shaders", "crashes", "logs", "nui", "temp"]
var cleanScan = null
var cleaning = false
var cleanRunning = false // RedM open: rows it holds open get a lock and are skipped
// Server cache is ticked for this visit only: remembered, every later clean would wipe every server's files.
var serverPicked = false

function cleanPicked() {
  var saved = null
  try { saved = JSON.parse(localStorage.getItem("cleanPicked")) } catch (e) {}
  return (cleanScan || []).filter(function (c) {
    if (c.id === "server") return serverPicked
    return saved ? saved.indexOf(c.id) !== -1 : c.on
  }).sort(function (a, b) { return CLEAN_ORDER.indexOf(a.id) - CLEAN_ORDER.indexOf(b.id) }).map(function (c) { return c.id })
}

function renderCleanup() {
  var box = document.getElementById("clean-list")
  if (!cleanScan) { box.innerHTML = new Array(5).join('<div class="check skeleton"></div>'); return }
  var picked = cleanPicked()
  var rows = cleanScan.slice().sort(function (a, b) { return CLEAN_ORDER.indexOf(a.id) - CLEAN_ORDER.indexOf(b.id) })
  box.innerHTML = rows.map(function (c) {
    var size = c.bytes == null ? "…" : c.bytes ? fmtBytes(c.bytes) : esc(t("clean.empty"))
    var lock = cleanRunning && c.redm ? '<i class="ph ph-lock-simple" title="' + esc(t("clean.lockedHint")) + '" aria-label="' + esc(t("clean.lockedHint")) + '"></i> ' : ''
    return '<label class="check' + (c.bytes === 0 ? " is-empty" : "") + '"><input type="checkbox" data-clean="' + c.id + '"' + (picked.indexOf(c.id) !== -1 ? " checked" : "") + '>' +
      '<span class="check-box"></span><span class="check-text"><span class="check-label">' + esc(t("clean." + c.id)) + '</span>' +
      '<span class="check-desc">' + esc(t("clean." + c.id + "Desc")) + '</span></span>' +
      '<span class="check-size">' + lock + size + '</span></label>'
  }).join("")
  updateCleanButton()
}

function cleanTotal() {
  var picked = cleanPicked()
  return (cleanScan || []).reduce(function (n, c) { return n + (picked.indexOf(c.id) !== -1 ? c.bytes || 0 : 0) }, 0)
}

function updateCleanButton() {
  var total = cleanTotal()
  document.getElementById("clean-btn-label").textContent = cleaning ? t("clean.running") : total ? t("clean.btn").replace("{size}", fmtBytes(total)) : t(cleanPicked().length ? "clean.none" : "clean.nothing")
  document.getElementById("clean-btn").disabled = cleaning || !total
  document.getElementById("clean-list").setAttribute("aria-busy", String(cleaning))
}

// Rows appear at once; each size fills in as its folder finishes measuring (temp is the slow one).
async function refreshCleanup() {
  var meta = await window.launcher.cleanupMeta()
  cleanRunning = (await window.launcher.redmInfo()).running
  cleanScan = meta.map(function (m) {
    var old = (cleanScan || []).find(function (c) { return c.id === m.id })
    return Object.assign({}, m, { bytes: old ? old.bytes : null })
  })
  renderCleanup()
  await Promise.all(meta.map(async function (m) {
    var r = await window.launcher.cleanupScanOne(m.id)
    var row = cleanScan.find(function (c) { return c.id === m.id })
    if (row && r) row.bytes = r.bytes
    renderCleanup()
  }))
}

function initCleanup(fail) {
  document.getElementById("clean-list").addEventListener("change", function (e) {
    if (!e.target.dataset.clean) return
    if (e.target.dataset.clean === "server") serverPicked = e.target.checked
    var ids = [].map.call(document.querySelectorAll("#clean-list input:checked"), function (i) { return i.dataset.clean })
      .filter(function (id) { return id !== "server" })
    localStorage.setItem("cleanPicked", JSON.stringify(ids))
    updateCleanButton()
  })
  document.getElementById("clean-btn").onclick = async function () {
    var ids = cleanPicked(), total = cleanTotal()
    if (!ids.length || cleaning) return
    var names = ids.map(function (id) { return t("clean." + id) }).join(", ")
    // RedM open: say before deleting which rows will be skipped, not after.
    cleanRunning = (await window.launcher.redmInfo()).running
    var locked = cleanRunning ? ids.filter(function (id) { var c = cleanScan.find(function (x) { return x.id === id }); return c && c.redm }) : []
    if (locked.length === ids.length) { say(t("tools.running")); renderCleanup(); return }
    var lockedNames = locked.map(function (id) { return t("clean." + id) }).join(", ")
    if (!(await confirmDialog(t("clean.confirmTitle").replace("{size}", fmtBytes(total)), names + ". " + t("clean.confirmMsg") +
      (locked.length ? " " + t("clean.locked").replace("{list}", lockedNames) : ""), t("clean.confirmOk"), { danger: true }))) return
    cleaning = true
    updateCleanButton()
    var r = await window.launcher.cleanupRun(ids)
    cleaning = false
    if (r.success) {
      say(t("clean.done").replace("{size}", fmtBytes(r.freed || 0)) + (r.failed ? " " + t("clean.skipped").replace("{n}", r.failed) : "") +
        (r.locked && r.locked.length ? " " + t("clean.locked").replace("{list}", r.locked.map(function (id) { return t("clean." + id) }).join(", ")) : ""))
    } else fail(r)
    refreshCleanup()
  }
}

// ── Graphics and performance ──

var lastGfx = null
async function refreshGraphics() {
  var g = await window.launcher.graphicsInfo()
  // Turned on here, but a new RedM build brought a new game exe without it: apply it to that one too.
  if (g.exes && !g.fsoOff && localStorage.getItem("gfxFso") === "true" && (await window.launcher.setFso(true))) g = await window.launcher.graphicsInfo()
  renderGraphics(g)
}

function renderGraphics(g) {
  lastGfx = g
  var fso = document.getElementById("gfx-fso")
  fso.checked = g.fsoOff
  fso.disabled = !g.exes
  // Disabled: say why, on the row's description.
  var desc = fso.closest(".switch-row").querySelector(".check-desc")
  desc.textContent = t("gfx.fsoDesc") + (g.exes ? "" : " " + t("gfx.fsoNone"))
  document.getElementById("gfx-prio").checked = localStorage.getItem("gfxPrio") === "true"
  var power = document.getElementById("gfx-power")
  power.checked = g.power === "ok" && localStorage.getItem("gfxPower") === "true"
  power.disabled = g.power !== "ok"
  document.getElementById("gfx-power-desc").textContent = g.power === "own" ? t("gfx.powerOwn") : t("gfx.powerDesc") + (g.power === "ok" ? "" : " " + t("gfx.powerNone"))
  document.getElementById("gfx-reset-row").hidden = !g.hasSettings
  renderWindows(g.windows)
  renderUndo()
}

// One row in the Tools lists: a label, a line under it, an optional button. warn: drawn as a problem.
function infoRow(o) {
  return '<div class="switch-row info-row' + (o.warn ? " warn" : "") + '">' +
    (o.warn ? '<i class="ph ph-warning-circle"></i>' : "") +
    '<span class="row-text">' + (o.label ? '<span class="check-label">' + esc(o.label) + '</span>' : "") +
    (o.desc ? '<span class="check-desc">' + esc(o.desc) + '</span>' : "") + '</span>' +
    (o.act && o.icon ? '<button type="button" class="btn glass icon-only" data-act="' + o.act + '" data-arg="' + esc(o.arg) + '" title="' + esc(o.btn) + '" aria-label="' + esc(o.btn) + '"><i class="ph ' + o.icon + '"></i></button>'
      : o.act ? '<button type="button" class="btn glass" data-act="' + o.act + '" data-arg="' + esc(o.arg) + '">' + esc(o.btn) + '</button>' : "") + '</div>'
}

// "2026-11-26" or a backup's "2026-11-26-14-02-33", in the player's date order. Numbers only: Electron
// has no month names for Georgian and would put English ones in a Georgian sentence.
function fmtDate(stamp, withTime) {
  var n = String(stamp || "").split("-").map(Number)
  var d = new Date(n[0], n[1] - 1, n[2], n[3] || 0, n[4] || 0)
  var opts = { year: "numeric", month: "2-digit", day: "2-digit" }
  if (withTime) { opts.hour = "2-digit"; opts.minute = "2-digit" }
  try { return d.toLocaleString(currentLang.replace("_", "-"), opts) } catch (e) { return d.toLocaleString() }
}

// Windows' own game settings: shown, never changed. Each opens its page in Windows Settings.
function renderWindows(w) {
  if (!w) return
  var open = function (arg) { return { act: "win-settings", arg: arg, btn: t("win.open"), icon: "ph-arrow-square-out" } }
  document.getElementById("win-list").innerHTML = [
    infoRow(Object.assign({ label: t("win.gameMode"), desc: t(w.gameMode ? "win.gameModeOn" : "win.gameModeOff"), warn: !w.gameMode }, open("gameMode"))),
    infoRow(Object.assign({ label: t("win.rec"), desc: t(w.recording ? "win.recOn" : "win.recOff"), warn: w.recording }, open("recording"))),
    infoRow(Object.assign({ label: t("win.gpu"), desc: t(w.gpuScheduling === null ? "win.gpuNone" : w.gpuScheduling ? "win.gpuOn" : "win.gpuOff") }, open("gpuScheduling"))),
  ].join("")
}

// ── Your PC ──

var pcData = null
var DRIVER_PAGES = {
  nvidia: "https://www.nvidia.com/en-us/drivers/",
  amd: "https://www.amd.com/en/support/download/drivers.html",
  intel: "https://www.intel.com/content/www/us/en/support/detect.html",
}

async function refreshPc() {
  if (pcData && pcData.gpus.length) return renderPc()
  renderPc()
  try { pcData = await window.launcher.pcInfo() } catch (e) { pcData = null }
  renderPc()
}

function renderPc() {
  var box = document.getElementById("pc-list")
  if (!pcData) { box.innerHTML = infoRow({ desc: t("pc.loading") }); return }
  var p = pcData, gb = Math.round(p.ramBytes / GB) + " GB"
  var rows = [
    infoRow({ label: t("pc.cpuLabel"), desc: t("pc.cpu").replace("{cpu}", p.cpu).replace("{n}", p.threads) }),
    infoRow({ label: t("pc.ramLabel"), desc: p.ramBytes < 7.5 * GB ? t("pc.ramLow").replace("{size}", gb) : gb, warn: p.ramBytes < 7.5 * GB }),
  ]
  p.gpus.forEach(function (g) {
    var date = g.date ? fmtDate(g.date) : ""
    var desc = g.old ? t("pc.gpuOld") : g.date ? t("pc.gpu") : t("pc.gpuNoDate")
    rows.push(infoRow({ label: t("pc.gpuLabel"), desc: desc.replace("{name}", g.name).replace("{v}", g.version).replace("{date}", date), warn: g.old,
      act: g.old && DRIVER_PAGES[g.vendor] ? "pc-driver" : null, arg: g.vendor, btn: t("pc.update") }))
  })
  if (!p.gpus.length) rows.push(infoRow({ label: t("pc.gpuLabel"), desc: t("pc.failed") }))
  if (p.windowsBuild) rows.push(infoRow({ label: t("pc.winLabel"), desc: t("pc.windows").replace("{n}", p.windowsBuild >= 22000 ? "11" : "10").replace("{b}", p.windowsBuild) }))
  box.innerHTML = rows.join("")
}

// For "Copy report for staff".
function pcReport() {
  if (!pcData) return []
  var p = pcData
  return ["PC: " + p.cpu + " (" + p.threads + " threads), " + Math.round(p.ramBytes / GB) + " GB RAM, Windows build " + (p.windowsBuild || "?")]
    .concat(p.gpus.map(function (g) { return "Graphics: " + g.name + ", driver " + g.version + (g.date ? " (" + g.date + ")" : "") }))
}

// ── Changes made by the launcher, each with its way back ──

var changes = null

async function refreshUndo() {
  try { changes = await window.launcher.changesInfo() } catch (e) { return }
  renderUndo()
}

function renderUndo() {
  if (!changes) return
  var c = changes, rows = []
  var undo = function (arg, btn) { return { act: "undo", arg: arg, btn: btn || t("undo.btn") } }
  if (c.channelWas && c.channelWas !== c.channel) {
    rows.push(infoRow(Object.assign({ label: t("undo.branch").replace("{b}", branchLabel(c.channel)).replace("{was}", branchLabel(c.channelWas)) },
      undo("branch", t("undo.branchBtn").replace("{was}", branchLabel(c.channelWas))))))
  }
  if (lastGfx && lastGfx.fsoOff) rows.push(infoRow(Object.assign({ label: t("undo.fso") }, undo("fso"))))
  if (localStorage.getItem("gfxPrio") === "true") rows.push(infoRow(Object.assign({ label: t("undo.prio") }, undo("prio"))))
  if (localStorage.getItem("gfxPower") === "true") rows.push(infoRow(Object.assign({ label: t("undo.power") }, undo("power"))))
  if (c.gfxBackup) rows.push(infoRow(Object.assign({ label: t("undo.gfx").replace("{date}", fmtDate(c.gfxBackup, true)) }, undo("gfx", t("undo.gfxBtn")))))
  c.modBackups.forEach(function (m) {
    rows.push(infoRow(Object.assign({ label: t(m.files === 1 ? "undo.mods1" : "undo.mods").replace("{n}", m.files).replace("{date}", fmtDate(m.name, true)) },
      undo("mods:" + m.name, t("undo.modsBtn")))))
  })
  document.getElementById("undo-list").innerHTML = rows.join("")
  document.getElementById("undo-desc").textContent = t(rows.length ? "undo.desc" : "undo.none")
}

async function undoChange(what) {
  // The switches undo through their own toggle, so the setting and its saved choice stay in step.
  if (what === "fso" || what === "prio" || what === "power") {
    var box = document.getElementById("gfx-" + what)
    box.checked = false
    box.dispatchEvent(new Event("change"))
    return
  }
  if (what === "branch") {
    var was = changes.channelWas, want = config.recommendedBranch
    if (want && want === changes.channel && !(await confirmDialog(t("undo.branchBtn").replace("{was}", branchLabel(was)) + "?",
      t("undo.branchWarn").replace("{server}", brand.name).replace("{b}", branchLabel(want)).replace("{was}", branchLabel(was)),
      t("undo.branchBtn").replace("{was}", branchLabel(was))))) return
    var r = await window.launcher.setChannel(was)
    r.success ? say(r.running ? t("ready.restartHint").replace("{b}", branchLabel(was)) : t("undo.done")) : toolFail(r)
    refreshTools()
    return refreshReady()
  }
  if (what === "gfx") {
    if (!(await confirmDialog(t("undo.gfxBtn"), t("undo.gfxMsg").replace("{date}", fmtDate(changes.gfxBackup, true)), t("undo.gfxBtn")))) return
    var g = await window.launcher.restoreGraphics()
    g.success ? say(t("undo.done")) : toolFail(g)
    return refreshTools()
  }
  if (what.indexOf("mods:") === 0) {
    if (!(await confirmDialog(t("undo.modsTitle"), t("undo.modsMsg").replace("{server}", brand.name), t("undo.modsBtn")))) return
    var m = await window.launcher.restoreMods(what.slice(5))
    m.success ? say(t("undo.done") + (m.kept ? " " + t("undo.modsKept") : "")) : toolFail(m)
    refreshUndo()
    refreshReady()
  }
}

function initGraphics(fail) {
  var bind = function (id, key, apply) {
    document.getElementById(id).addEventListener("change", async function () {
      localStorage.setItem(key, String(this.checked))
      var ok = await apply(this.checked)
      say(ok === false ? t("tools.failed").replace("{code}", "registry") : t("tools.done"))
      if (ok === false) refreshGraphics() // show what Windows really has
      renderUndo()
    })
  }
  bind("gfx-fso", "gfxFso", window.launcher.setFso)
  bind("gfx-prio", "gfxPrio", window.launcher.setPriorityBoost)
  bind("gfx-power", "gfxPower", window.launcher.setPowerBoost)
  document.getElementById("gfx-reset").onclick = async function () {
    if (!(await confirmDialog(t("gfx.reset"), t("gfx.resetDesc"), t("gfx.resetBtn")))) return
    var r = await window.launcher.resetGraphics()
    r.success ? say(t("tools.done")) : fail(r)
    refreshGraphics()
    refreshUndo()
  }
  // Re-apply on every launch: a new RedM game build brings a new exe that needs the same settings.
  // Up to 1.1.6 the launcher could turn on "High performance GPU" for the game (see graphics.js undoGpu).
  // Undo it once, only where the launcher itself turned it on: a setting the player made in Windows stays.
  // Keeps trying on each launch until every value is gone.
  if (localStorage.getItem("gfxGpu") === "true") window.launcher.undoGpu().then(function (ok) { if (ok) localStorage.removeItem("gfxGpu") })
  if (localStorage.getItem("gfxFso") === "true") window.launcher.setFso(true)
  if (localStorage.getItem("gfxPrio") === "true") window.launcher.setPriorityBoost(true)
  if (localStorage.getItem("gfxPower") === "true") window.launcher.setPowerBoost(true)
}

// ── Helpers that solve player problems: ready-to-play checklist, Fix my game, crash helper,
//    back-online alert and auto-join when full ──

var wait = function (ms) { return new Promise(function (r) { setTimeout(r, ms) }) }
var GB = 1073741824

function branchLabel(channel) {
  var p = (config.branches || []).find(function (b) { return b.channel === channel })
  return p ? p.label : channel
}

// Windows notification, only when the launcher isn't the window you're looking at.
function notify(title, body) {
  if (document.hasFocus()) { say(title); return }
  try {
    var n = new Notification(title, { body: body || "", icon: brand.logo || "../../assets/icon.png" })
    n.onclick = function () { window.launcher.focusWindow(); switchNav("home") }
  } catch (e) {}
}

// Ready to play

var ready = null
var readyAt = 0

async function refreshReady() {
  try { ready = await window.launcher.readiness() } catch (e) { return }
  readyAt = Date.now()
  renderReady()
}

function readyItems() {
  var r = ready, items = []
  items.push({ ok: r.redm, text: t(r.redm ? "ready.redm" : "ready.redmBad"), fix: "get-redm", fixLabel: t("ready.get") })
  if (r.redm) items.push({ ok: r.game, text: t(r.game ? "ready.game" : "ready.gameBad"), fix: "open-redm", fixLabel: t("settings.openGame") })
  if (r.redm) items.push({ ok: r.links, text: t(r.links ? "ready.links" : "ready.linksBad"), fix: "repair-links", fixLabel: t("ready.repair") })
  if (config.recommendedBranch) {
    var okB = r.channel === config.recommendedBranch
    items.push({ ok: okB, text: t(okB ? "ready.branch" : "ready.branchBad").replace("{server}", brand.name).replace("{b}", branchLabel(config.recommendedBranch)), fix: "set-branch", fixLabel: t("ready.switch") })
  }
  if (nameInfo && r.redm) {
    var madeUp = nameMadeUp()
    items.push({ ok: !madeUp, text: !nameInfo.name ? t("ready.nameNone") : madeUp ? t("ready.nameBad").replace("{name}", nameInfo.name) : t("ready.name").replace("{name}", nameInfo.name), fix: "name", fixLabel: t("ready.change") })
  }
  if (r.freeBytes != null) {
    var okD = r.freeBytes > 15 * GB
    items.push({ ok: okD, text: t(okD ? "ready.disk" : "ready.diskBad").replace("{size}", fmtBytes(r.freeBytes)), fix: "free-space", fixLabel: t("ready.freeUp") })
  }
  // Visual mods in RedM's data folders: an approved one is fine, anything else the server's anticheat may flag.
  if (r.mod && r.mod.state !== "none") {
    var okM = r.mod.state === "approved"
    items.push({ ok: okM, text: t(okM ? "ready.mod" : r.mod.files.length === 1 ? "ready.modBad1" : "ready.modBad").replace("{name}", r.mod.name).replace("{server}", brand.name).replace("{n}", r.mod.files.length), fix: "remove-mods", fixLabel: t("ready.remove") })
  }
  // Hints, not problems: apps that hook into games, story-mode mods in the RDR2 folder.
  if (r.hooks && r.hooks.length) items.push({ ok: true, info: true, text: t("ready.hooks").replace("{apps}", r.hooks.join(", ")) })
  if (r.storyMods && r.storyMods.length) {
    var files = r.storyMods.slice(0, 4).join(", ") + (r.storyMods.length > 4 ? ", …" : "")
    items.push({ ok: true, info: true, text: t("ready.storyMods").replace("{files}", files), fix: "open-game-folder", fixLabel: t("ready.openFolder") })
  }
  return items
}

function renderReady() {
  if (!ready) return
  var items = readyItems()
  var bad = items.filter(function (i) { return !i.ok }).length
  document.getElementById("ready").hidden = false
  var btn = document.getElementById("ready-btn")
  btn.className = "ready-btn " + (bad ? "warn" : "ok")
  btn.innerHTML = '<i class="ph ' + (bad ? "ph-warning-circle" : "ph-check-circle") + '"></i><span>' +
    esc(bad ? (bad === 1 ? t("ready.issue1") : t("ready.issues").replace("{n}", bad)) : t("ready.ok")) + '</span><i class="ph ph-caret-up"></i>'
  document.getElementById("ready-panel").innerHTML = items.map(function (i) {
    return '<div class="ready-item ' + (i.info ? "info" : i.ok ? "ok" : "bad") + '"><i class="ph ' + (i.info ? "ph-info" : i.ok ? "ph-check-circle" : "ph-warning-circle") + '"></i>' +
      '<span class="row-text">' + esc(i.text) + '</span>' +
      (!i.fix || (i.ok && !i.info) ? '' : '<button type="button" class="btn accent" data-act="ready-fix" data-arg="' + i.fix + '">' + esc(i.fixLabel) + '</button>') + '</div>'
  }).join("") +
    '<div class="ready-foot"><span>' + esc(t("ready.trouble")) + '</span><button type="button" class="btn glass" data-act="fix-game"><i class="ph ph-first-aid-kit"></i>' + esc(t("fix.btn")) + '</button></div>'
  refreshJoinButton() // "Get RedM" while RedM is missing
  renderWelcome()
}

function toggleReady(open) {
  var panel = document.getElementById("ready-panel")
  panel.hidden = open === undefined ? !panel.hidden : !open
  document.getElementById("ready-btn").setAttribute("aria-expanded", String(!panel.hidden))
}

async function readyFix(what) {
  if (what === "get-redm") return window.launcher.openExternal("https://redm.net")
  if (what === "open-redm") return openGame()
  if (what === "free-space") { toggleReady(false); return switchNav("tools") }
  if (what === "open-game-folder") { if ((await window.launcher.openFolder("game")) === "missing") say(t("tools.noFolder")); return }
  if (what === "name") { toggleReady(false); switchNav("settings"); return document.getElementById("settings-name").focus() }
  if (what === "remove-mods") {
    var res = await window.launcher.removeMods()
    say(res.success ? t(res.moved === 1 ? "ready.modRemoved1" : "ready.modRemoved").replace("{n}", res.moved).replace("{folder}", res.folder || "")
      : t(res.error === "running" ? "tools.running" : "ready.modFailed"))
    return refreshReady()
  }
  if (what === "set-branch") {
    var b = await window.launcher.setChannel(config.recommendedBranch)
    if (!b.success) toolFail(b)
    else say(b.running ? t("ready.restartHint").replace("{b}", branchLabel(config.recommendedBranch)) : t("tools.done")) // a running RedM keeps its old version
  }
  if (what === "repair-links") {
    var l = await window.launcher.repairLinks()
    say(l && l.success ? t("tools.done") : l && l.error === "not_installed" ? t("tools.notInstalled") : t("ready.repairFailed"))
  }
  refreshReady()
}

// Before joining: offer to switch to the server's game version if it's set and different.
// `ready` is fresh here (joinServer refreshed it).
async function branchCheckBeforeJoin() {
  var want = config.recommendedBranch
  if (!want || !ready || ready.channel === want) return true
  var label = branchLabel(want)
  if (!(await confirmDialog(t("branch.switchTitle").replace("{b}", label), t("branch.switchMsg").replace("{server}", brand.name).replace("{b}", label), t("branch.switchOk")))) return false
  setJoinBusy(t("join.switching"))
  var r = await window.launcher.setChannel(want)
  if (!r.success) { toolFail(r); return false }
  if (r.running) {
    await window.launcher.killRedm() // a running RedM keeps its old version until restarted
    await wait(1500)
  }
  await refreshReady()
  return true
}

// Fix my game: the safe fixes, in order, with a visible list of what happened.

async function fixMyGame() {
  var r = ready || await window.launcher.readiness()
  // Nothing to fix without RedM: say what's missing instead of failing every step.
  if (!r.redm) { showErrorDialog(t("dialog.notFound").replace("{game}", "RedM"), t("dialog.notFoundMsg").replace("{game}", "RedM"), "https://redm.net"); return }
  if (!(await confirmDialog(t("fix.confirmTitle"), t("fix.confirmMsg"), t("fix.btn")))) return
  var steps = [
    { label: t("fix.stepClose"), run: async function () { await window.launcher.killRedm(); await wait(2000) } },
    { label: t("fix.stepCache"), run: async function () {
      var x = await window.launcher.cleanupRun(["server", "app"])
      if (!x.success) throw new Error(x.error)
      return fmtBytes(x.freed || 0)
    } },
  ]
  if (config.recommendedBranch && r.channel !== config.recommendedBranch) {
    steps.push({ label: t("fix.stepBranch").replace("{b}", branchLabel(config.recommendedBranch)), run: async function () {
      var x = await window.launcher.setChannel(config.recommendedBranch)
      if (!x.success) throw new Error(x.error)
    } })
  }
  var o = document.createElement("div")
  o.className = "error-overlay"
  o.innerHTML = '<div class="error-dialog wide" role="dialog" aria-modal="true"><h3 class="error-title">' + esc(t("fix.title")) + '</h3>' +
    '<ul class="steps">' + steps.map(function (s) { return '<li><i class="ph ph-circle"></i><span>' + esc(s.label) + '</span></li>' }).join("") + '</ul>' +
    '<p class="error-msg" data-role="result" aria-live="polite"></p>' +
    '<div class="error-actions" data-role="actions" hidden><button class="error-btn secondary" data-act="dialog-close">' + esc(t("dialog.ok")) + '</button>' +
    '<button class="error-btn" data-act="fix-join">' + esc(t("join.default")) + '</button></div></div>'
  showOverlay(o)
  var lis = o.querySelectorAll(".steps li"), failed = 0
  for (var i = 0; i < steps.length; i++) {
    lis[i].firstChild.outerHTML = '<span class="join-spinner"></span>'
    try {
      var extra = await steps[i].run()
      lis[i].className = "done"
      lis[i].firstChild.outerHTML = '<i class="ph ph-check-circle"></i>'
      if (extra) lis[i].lastChild.textContent += " (" + extra + ")"
    } catch (e) {
      failed++
      lis[i].className = "fail"
      lis[i].firstChild.outerHTML = '<i class="ph ph-x-circle"></i>'
    }
  }
  o.querySelector('[data-role="result"]').textContent = failed ? t("fix.partly") : t("fix.done")
  o.querySelector('[data-role="actions"]').hidden = false
  o.querySelector('[data-act="fix-join"]').focus()
  refreshReady()
  if (document.body.dataset.view === "tools") refreshTools()
}

// Crash helper: main.js reads RedM's log when the game closes and tells us if it crashed.

var lastCrash = null
function showCrash(c) {
  lastCrash = c
  if (!pcData) window.launcher.pcInfo().then(function (p) { pcData = p }).catch(function () {})
  closeOverlays() // a dialog left open from before the game started (a pending join question) is stale now
  var o = document.createElement("div")
  o.className = "error-overlay crash"
  // A graphics crash gets the fix its message recommends, one click away.
  var fix = c.cause === "graphics"
    ? '<button class="error-btn" data-act="crash-reset-gfx">' + esc(t("crash.resetGfx")) + '</button>'
    : '<button class="error-btn" data-act="fix-game">' + esc(t("fix.btn")) + '</button>'
  o.innerHTML = '<div class="error-dialog wide" role="alertdialog" aria-modal="true"><h3 class="error-title">' + esc(t("crash.title")) + '</h3>' +
    '<p class="error-msg">' + esc(t("crash.cause." + c.cause)) + '</p>' +
    '<div class="crash-msg">' + esc(c.message) + '</div>' +
    '<div class="error-actions"><button class="error-btn secondary" data-act="dialog-close">' + esc(t("dialog.ok")) + '</button>' +
    '<button class="error-btn secondary" data-act="crash-logs"><i class="ph ph-folder-open"></i> ' + esc(t("crash.openLogs")) + '</button>' +
    '<button class="error-btn secondary" data-act="crash-copy"><i class="ph ph-copy"></i> ' + esc(t("crash.copy")) + '</button>' +
    fix + '</div></div>'
  showOverlay(o, '[data-act="dialog-close"]')
  notify(t("crash.title"), t("crash.cause." + c.cause))
}

function crashReport() {
  var c = lastCrash || {}
  return [
    brand.name + " launcher " + appVersion,
    "Time: " + new Date().toString(),
    "RedM version (branch): " + (ready ? ready.channel : "?"),
  ].concat(pcReport(), [
    "Log file: " + (c.log || "?"),
    "",
    "Crash message:",
    c.message || "",
    "",
    "Last log lines before the crash:",
    c.context || "",
  ]).join("\n")
}

// Back-online alert + auto-join when full

var lastOnline = null
var waitingSlot = false
var slotTimer = null

function serverFull() {
  var d = featuredLive
  return !!(d && d.online && d.maxClients && d.clients >= d.maxClients)
}

function refreshJoinButton() {
  if (!joining) document.getElementById("join-btn").innerHTML = getJoinBtnDefault()
}

function onFeaturedStatus(data) {
  var online = !!(data && data.online)
  if (lastOnline === false && online) notify(t("alert.online").replace("{server}", brand.name), t("alert.onlineBody"))
  // Only a real "down" counts as offline: a Cfx rate limit or our own lost internet says nothing about
  // the server, and would end in a false "back online" alert.
  if (online || (data && data.reason === "down")) lastOnline = online
  refreshJoinButton()
}

function startWaiting() {
  waitingSlot = true
  refreshJoinButton()
  say(t("join.waitingToast"))
  slotTimer = setInterval(async function () {
    await fetchServerStatus()
    if (featuredLive && featuredLive.online && !serverFull()) {
      stopWaiting()
      notify(t("alert.slot").replace("{server}", brand.name))
      joinServer({ auto: true })
    }
  }, 10000)
}

function stopWaiting() {
  waitingSlot = false
  clearInterval(slotTimer)
  refreshJoinButton()
}

// ── First start: set up everything safe by itself, then say what it did ──
// Applied once (localStorage firstRunDone). The welcome card stays until it's closed or a name is saved.

var nameInfo = null

async function loadName() {
  try { nameInfo = await window.launcher.getName() } catch (e) { nameInfo = null }
  ;["welcome-name", "settings-name"].forEach(function (id) {
    var el = document.getElementById(id)
    if (el && nameInfo && document.activeElement !== el) el.value = nameInfo.name || ""
  })
  renderWelcomeHint()
  renderReady()
}

async function firstRun() {
  if (!localStorage.getItem("firstRunDone")) {
    var r = ready || (await window.launcher.readiness().catch(function () { return null }))
    var done = ["lang", "server"]
    if (r && r.redm && !r.links) {
      var x = await window.launcher.repairLinks().catch(function () { return null })
      if (x && x.success) done.push("links")
    }
    if (updState.state !== "dev") done.push("shortcut") // shortcuts are made by the installed app
    localStorage.setItem("firstRunDone", JSON.stringify(done))
    refreshReady()
  }
  if (!localStorage.getItem("welcomeClosed")) renderWelcome()
}

function renderWelcome() {
  var done = []
  if (!localStorage.getItem("firstRunDone")) return // first start still being set up (firstRun draws it)
  try { done = JSON.parse(localStorage.getItem("firstRunDone")) || [] } catch (e) {}
  if (!Array.isArray(done) || localStorage.getItem("welcomeClosed")) return
  done = done.filter(function (k) { return k !== "gpu" }) // listed by 1.1.4–1.1.6; undone since
  document.getElementById("welcome-title").textContent = t("welcome.title").replace("{server}", brand.name)
  // Open checklist items other than the name (asked for right below): point at them, don't claim all is done.
  var todo = ready ? readyItems().filter(function (i) { return !i.ok && i.fix !== "name" }).length : 0
  document.getElementById("welcome-done").innerHTML = done.map(function (k) {
    // Native name from the launcher's own list (the system's language names don't cover Georgian).
    var lang = (i18nLanguageList.find(function (l) { return l.code === currentLang }) || {}).name || currentLang
    return '<li><i class="ph ph-check-circle"></i>' + esc(t("welcome." + k).replace("{server}", brand.name).replace("{lang}", lang)) + '</li>'
  }).join("") + (todo ? '<li class="todo"><i class="ph ph-warning-circle"></i>' + esc(t("welcome.todo")) + '</li>' : '')
  renderWelcomeHint()
  document.getElementById("welcome").hidden = false
}

function renderWelcomeHint() {
  var hint = document.getElementById("welcome-hint")
  if (!hint) return
  hint.textContent = !nameInfo ? "" : !nameInfo.name ? t("name.none") : nameMadeUp() ? t("name.madeUp") : t("name.current")
}

// RedM's own random names look like BoldMoth3983, but so can a name a player picks on purpose:
// one saved through the launcher never counts as random.
function nameMadeUp() {
  return !!nameInfo && (!nameInfo.name || (nameInfo.madeUp && localStorage.getItem("namePicked") !== nameInfo.name))
}

function closeWelcome() {
  localStorage.setItem("welcomeClosed", "1")
  document.getElementById("welcome").hidden = true
}

async function saveName(inputId) {
  var input = document.getElementById(inputId)
  var r = await window.launcher.setName(input.value)
  if (r.success) {
    input.setCustomValidity("")
    input.value = r.name // as saved: trimmed, single spaces
    localStorage.setItem("namePicked", r.name)
    say(t("name.saved").replace("{name}", r.name))
    if (inputId === "welcome-name") closeWelcome()
    loadName()
  } else {
    // Shown next to the field and kept until the text changes (the toast alone was easy to miss).
    input.setCustomValidity(t(r.error === "running" ? "name.running" : r.error === "invalid" ? "name.invalid" : "name.failed"))
    input.reportValidity()
    input.focus()
  }
}

function initHelpers() {
  refreshReady()
  loadName()
  ;["welcome-name", "settings-name"].forEach(function (id) {
    var el = document.getElementById(id)
    el.addEventListener("keydown", function (e) { if (e.key === "Enter") saveName(id) })
    el.addEventListener("input", function () { el.setCustomValidity("") })
  })
  // Let readiness and the update state arrive first, so the setup knows what this PC needs.
  setTimeout(firstRun, 1200)
  window.launcher.onGameCrashed(showCrash)
  // Re-check readiness when you come back to the launcher (you may have fixed something outside it).
  window.addEventListener("focus", function () {
    if (Date.now() - readyAt > 30000) refreshReady()
    if (document.body.dataset.view === "tools") { refreshGraphics(); refreshUndo() }
  })
  // Close the checklist when clicking anywhere else.
  document.addEventListener("click", function (e) {
    var panel = document.getElementById("ready-panel")
    if (!panel.hidden && !e.target.closest(".ready")) toggleReady(false)
  })
  // Keyboard: Escape closes the checklist and the gallery viewer; arrows move through the gallery;
  // Enter/Space work on the few clickable things that aren't buttons (gallery images).
  document.addEventListener("keydown", function (e) {
    var lightboxOpen = document.getElementById("lightbox").style.display === "flex"
    if (e.key === "Escape") {
      if (lightboxOpen) return closeLightbox()
      if (!document.getElementById("ready-panel").hidden) { toggleReady(false); document.getElementById("ready-btn").focus() }
      return
    }
    if (lightboxOpen && (e.key === "ArrowLeft" || e.key === "ArrowRight")) return lightboxNav(e.key === "ArrowLeft" ? -1 : 1)
    var el = e.target
    if ((e.key === "Enter" || e.key === " ") && el.dataset && el.dataset.act && !/^(BUTTON|A|INPUT)$/.test(el.tagName)) { e.preventDefault(); el.click() }
  })
}

// One click handler for the whole UI. There are no inline onclick attributes, so the strict
// Content-Security-Policy in index.html can refuse any script that isn't the launcher's own.
document.addEventListener("click", function (e) {
  var el = e.target.closest("[data-act]")
  if (!el) return
  var a = el.dataset.arg
  switch (el.dataset.act) {
    case "nav": switchNav(a); break
    case "min": window.launcher.minimize(); break
    case "max": window.launcher.maximize(); break
    case "close": window.launcher.close(); break
    case "join": joinServer(); break
    case "join-dev": joinAddress(brand.devCfxCode, null, "Tiflisi DEV"); break
    case "entry": toggleEntry(el, a); break
    case "story": openStory(a.split("|")[0], a.split("|")[1]); break
    case "lightbox-open": openLightbox(+a); break
    case "lightbox-close": closeLightbox(); break
    case "lightbox-nav": lightboxNav(+a); break
    case "dialog-close": closeOverlay(el); break
    case "dialog-download": window.launcher.openExternal(a); closeOverlay(el); break
    case "update": window.launcher.installUpdate(); break
    case "ready-toggle": toggleReady(); break
    case "welcome-close": closeWelcome(); break
    case "name-save": saveName(a); break
    case "ready-fix": readyFix(a); break
    case "fix-game": closeOverlays(); toggleReady(false); fixMyGame(); break
    case "fix-join": closeOverlay(el); switchNav("home"); joinServer(); break // Home shows "Connecting…"
    case "crash-copy": window.launcher.copyText(crashReport()).then(function () { say(t("crash.copied")) }); break
    case "crash-logs": window.launcher.openFolder("logs"); break
    case "crash-reset-gfx": closeOverlay(el); window.launcher.resetGraphics().then(function (r) { r.success ? say(t("tools.done")) : toolFail(r) }); break
    case "source": window.launcher.openExternal(SOURCE_URL); break
    case "build-log": if (buildInfo) window.launcher.openExternal(buildInfo.run); break
    case "win-settings": window.launcher.openWindowsSettings(a); break
    case "pc-driver": if (DRIVER_PAGES[a]) window.launcher.openExternal(DRIVER_PAGES[a]); break
    case "undo": undoChange(a); break
  }
})
document.addEventListener("submit", function (e) { e.preventDefault() })

document.addEventListener("DOMContentLoaded", init)
